from typing import Dict, List, Tuple

class ManualBrowser:
    def __init__(self):
        self.entries = self.load_entries()
        self.current_page = 0
        self.entries_per_page = 10
        self.total_pages = (len(self.entries) + self.entries_per_page - 1) // self.entries_per_page
        self.command_index = self.create_command_index()
        self.current_menu = "MAIN"
        self.data_flow = self.create_data_flow()

    def create_command_index(self):
        index = {
            'INIT': {},
            'GATEWAY': {},
            'BUFFER': {},
            'PROCESS': {},
            'HASH': {},
            'CIPHER': {},
            'NETWORK': {},
            'MEMORY': {},
            'KEY': {},
            'ACCESS': {}
        }

        for i, (addr, cmd) in enumerate(self.entries):
            cmd_parts = cmd.split('_')
            cmd_type = cmd_parts[0]
            
            if cmd_type in index:
                if 'commands' not in index[cmd_type]:
                    index[cmd_type]['commands'] = []
                index[cmd_type]['commands'].append((addr, cmd, i+1))

        return index

